#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// float4-vectorized epilogue for channels_per_group == 32.
// 8 threads per group, each thread handles 4 consecutive channels (one float4).
// Sub-warp reduction over 8 lanes using __shfl_down_sync with mask 0xff per subgroup.
//
// Layout: blockDim.x = 256 => 32 groups per block, each group is 8 consecutive threads.
// warp_group_id = global thread index / 8  => identifies the (row, group) pair.
// lane8 = thread index % 8                 => which float4 slot within the group.
__global__ void fused_gn_swish_mul_swish_f4_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    const float* __restrict__ mul_weight,
    float*       __restrict__ out,
    int rows,
    int channels,
