// ---------------------------------------------------------------------------
// cuBLASLt GEMM helper
// ---------------------------------------------------------------------------

struct CublasLtState {
    cublasLtHandle_t handle = nullptr;
    cublasLtMatmulDesc_t   op_desc   = nullptr;
    cublasLtMatrixLayout_t layout_a  = nullptr;
    cublasLtMatrixLayout_t layout_b  = nullptr;
    cublasLtMatrixLayout_t layout_c  = nullptr;
    cublasLtMatmulHeuristicResult_t algo_result = {};
    void*  workspace     = nullptr;
    size_t workspace_size = 32 * 1024 * 1024;  // 32 MB
    bool   initialized   = false;
    int    cached_M = 0, cached_N = 0, cached_K = 0;
};

static CublasLtState g_lt_state;

static bool init_cublaslt(int M, int N, int K) {
    if (g_lt_state.initialized &&
        g_lt_state.cached_M == M &&
        g_lt_state.cached_N == N &&
        g_lt_state.cached_K == K) {
        return true;
    }

    // Destroy old descriptors if re-initializing
    if (g_lt_state.op_desc)  { cublasLtMatmulDescDestroy(g_lt_state.op_desc);  g_lt_state.op_desc  = nullptr; }
    if (g_lt_state.layout_a) { cublasLtMatrixLayoutDestroy(g_lt_state.layout_a); g_lt_state.layout_a = nullptr; }
    if (g_lt_state.layout_b) { cublasLtMatrixLayoutDestroy(g_lt_state.layout_b); g_lt_state.layout_b = nullptr; }
    if (g_lt_state.layout_c) { cublasLtMatrixLayoutDestroy(g_lt_state.layout_c); g_lt_state.layout_c = nullptr; }

    if (!g_lt_state.handle) {
        if (cublasLtCreate(&g_lt_state.handle) != CUBLAS_STATUS_SUCCESS) return false;
    }

    if (!g_lt_state.workspace) {
        cudaMalloc(&g_lt_state.workspace, g_lt_state.workspace_size);
    }

    // op: compute C = A * B^T  where A=[M,K], B=[N,K] (row-major weight matrix)
    // cuBLAS col-major: C^T = B * A^T
    // We compute: out[M,N] = x[M,K] * weight^T[K,N]
    // In col-major terms: out_col[N,M] = weight_col[N,K] * x_col^T[K,M]
    // => transa=N (weight stored as [N,K] col-major = N rows K cols), transb=T for x
    cublasOperation_t transa = CUBLAS_OP_T;  // weight: treat as K x N col-major => out = weight^T * x
    cublasOperation_t transb = CUBLAS_OP_N;

    cublasLtMatmulDescCreate(&g_lt_state.op_desc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    cublasLtMatmulDescSetAttribute(g_lt_state.op_desc, CUBLASLT_MATMUL_DESC_TRANSA,
                                   &transa, sizeof(transa));
    cublasLtMatmulDescSetAttribute(g_lt_state.op_desc, CUBLASLT_MATMUL_DESC_TRANSB,
                                   &transb, sizeof(transb));

    // Layout A: weight [N, K] stored row-major => col-major view is [K, N] with ld=N
    cublasLtMatrixLayoutCreate(&g_lt_state.layout_a, CUDA_R_32F, K, N, K);
    // Layout B: x [M, K] stored row-major => col-major view is [K, M] with ld=K
    cublasLtMatrixLayoutCreate(&g_lt_state.layout_b, CUDA_R_32F, K, M, K);
    // Layout C: out [M, N] stored row-major => col-major view is [N, M] with ld=N
    cublasLtMatrixLayoutCreate(&g_lt_state.layout_c, CUDA_R_32F, N, M, N);

    // Find best algorithm
    cublasLtMatmulPreference_t pref;
    cublasLtMatmulPreferenceCreate(&pref);
    cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                                         &g_lt_state.workspace_size, sizeof(g_lt_state.workspace_size));

    int returned = 0;
    cublasStatus_t stat = cublasLtMatmulAlgoGetHeuristic(
        g_lt_state.handle, g_lt_state.op_desc,
        g_lt_state.layout_a, g_lt_state.layout_b,
        g_lt_state.layout_c, g_lt_state.layout_c,
        pref, 1, &g_lt_state.algo_result, &returned);
    cublasLtMatmulPreferenceDestroy(pref);

    g_lt_state.initialized = (stat == CUBLAS_STATUS_SUCCESS && returned > 0);
    if (g_lt_state.initialized) {
        g_lt_state.cached_M = M;
        g_lt_state.cached_N = N;
        g_lt_state.cached_K = K;
    }
    return g_lt_state.initialized;
}

