    int group_in_warp = lane >> 3;
    unsigned mask     = 0xFFu << (group_in_warp * 8);

    lsum  += __shfl_down_sync(mask, lsum,  4);
    lsum  += __shfl_down_sync(mask, lsum,  2);
    lsum  += __shfl_down_sync(mask, lsum,  1);
    lsum2 += __shfl_down_sync(mask, lsum2, 4);
    lsum2 += __shfl_down_sync(mask, lsum2, 2);
    lsum2 += __shfl_down_sync(mask, lsum2, 1);

    int src_lane = group_in_warp * 8;
    float mean    = __shfl_sync(mask, lsum,  src_lane) * (1.0f / 32.0f);
    float var     = __shfl_sync(mask, lsum2, src_lane) * (1.0f / 32.0f) - mean * mean;
    float inv_std = rsqrtf(var + eps);

    float4 gw = __ldg((const float4*)(gn_weight  + ch_base));
    float4 gb = __ldg((const float4*)(gn_bias    + ch_base));
    float4 mw = __ldg((const float4*)(mul_weight + ch_base));

    float n0 = (v.x - mean) * inv_std * gw.x + gb.x;
    float n1 = (v.y - mean) * inv_std * gw.y + gb.y;
    float n2 = (v.z - mean) * inv_std * gw.z + gb.z;
    float n3 = (v.w - mean) * inv_std * gw.w + gb.w;

    float s0 = n0 / (1.0f + __expf(-n0));
    float s1 = n1 / (1.0f + __expf(-n1));
    float s2 = n2 / (1.0f + __expf(-n2));
    float s3 = n3 / (1.0f + __expf(-n3));

    float a0 = s0 * mw.x; float a1 = s1 * mw.y;
    float a2 = s2 * mw.z; float a3 = s3 * mw.w;

    float4 res;
    res.x = a0 / (1.0f + __expf(-a0));
    res.y = a1 / (1.0f + __expf(-a1));
    res.z = a2 / (1.0f + __expf(-a2));
    res.w = a3 / (1.0f + __expf(-a3));

    reinterpret_cast<float4*>(out + base_idx)[0] = res;
}

__global__ void fused_gn_swish_mul_swish_general_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    const float* __restrict__ mul_weight,
    float*       __restrict__ out,
    int rows, int channels, int num_groups, int channels_per_group, float eps)
{
    extern __shared__ float smem[];
    float* s_sum  = smem;
    float* s_sum2 = smem + blockDim.x;

    int group   = blockIdx.x % num_groups;
    int row     = blockIdx.x / num_groups;
    int ch_base = group * channels_per_group;
    int tid     = threadIdx.x;

    float local_sum = 0.f, local_sum2 = 0.f;
    for (int i = tid; i < channels_per_group; i += blockDim.x) {
        float v = x[row * channels + ch_base + i];
        local_sum  += v;
        local_sum2 += v * v;
    }
    s_sum[tid]  = local_sum;
    s_sum2[tid] = local_sum2;
    __syncthreads();

    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid]  += s_sum[tid + stride];
            s_sum2[tid] += s_sum2[tid + stride];
        }
        __syncthreads();
    }

    float mean    = s_sum[0]  / (float)channels_per_group;
    float var     = s_sum2[0] / (float)channels_per_group - mean * mean;
    float inv_std = rsqrtf(var + eps);

    for (int i = tid; i < channels_per_group; i += blockDim.x) {
        int ch = ch_base + i;
        float v = x[row * channels + ch];
        float normed = (v - mean) * inv_std * gn_weight[ch] + gn_bias[ch];
        float s1 = normed / (1.0f + __expf(-normed));
        float am = s1 * mul_weight[ch];
        float res = am / (1.0f + __expf(-am));
        out[row * channels + ch] = res;
    }
}

static void launch_epilogue(
    float* ptr,
    const float* gn_weight_ptr,
    const float* gn_bias_ptr,
    const float* mul_weight_ptr,
    int rows, int channels, int num_groups, float eps)
{
    int cpg = channels / num_groups;
    if (cpg == 32) {
        int total_threads     = rows * num_groups * 8;
        int threads_per_block = 256;
        int blocks = (total_threads + threads_per_block - 1) / threads_per_block;
        fused_gn_swish_mul_swish_f4_kernel<<<blocks, threads_per_block>>>(
            ptr, gn_weight_ptr, gn_bias_ptr, mul_weight_ptr, ptr,
            rows, channels, num_groups, eps);
    } else {
        int threads = 128;
        int blocks  = rows * num_groups;
        size_t smem = 2 * threads * sizeof(float);
        fused_gn_swish_mul_swish_general_kernel<<<blocks, threads, smem>>>(
            ptr, gn_weight_ptr, gn_bias_ptr, mul_weight_ptr, ptr,
            rows, channels, num_groups, cpg, eps);
    }
}

// ---------------------------------------------------------------------------
// cuBLASLt GEMM helper
// ---------------------------------------------------------------------------

struct CublasLtState {
    cublasLtHandle_t handle = nullptr;
    cublasLtMatmulDesc_t   op_desc   = nullptr;
    cublasLtMatrixLayout_t layout_a  = nullptr;
    cublasLtMatrixLayout_t layout_b  = nullptr;
    cublasLtMatrixLayout_t layout_c  = nullptr;
    cublasLtMatmulHeuristicResult_t algo_result = {};
    void*  workspace     = nullptr;
    size_t workspace_size = 32 * 1024 * 1024;
    bool   initialized   = false;
    int    cached_M = 0, cached_N = 0, cached_K = 0;
};

static CublasLtState g_lt_state;

static bool init_cublaslt(int M, int N, int K) {
    if (g_lt_state.initialized &&
        g_lt_state.cached_M == M &&
        g_lt_state.cached_N == N &&
        g_lt_state.cached_K == K) {
        return true;
    }

    if (g_lt_state.op_desc)  { cublasLtMatmulDescDestroy(g_lt_state.op_desc);  g_lt_state.op_desc  = nullptr; }
    if (g_lt_state.layout_a) { cublasLtMatrixLayoutDestroy(g_lt_state.layout_a); g_lt_state.layout_a = nullptr; }
    if (g_lt_state.layout_b) { cublasLtMatrixLayoutDestroy(g_lt_state.layout_b); g_lt_state.layout_b = nullptr; }
    if (g_lt_state.layout_c) { cublasLtMatrixLayoutDestroy(g_lt_state.layout_c); g_lt_state.layout_c = nullptr; }

    if (!g_lt_state.handle) {
        if (cublasLtCreate(&g_lt_state.handle) != CUBLAS_STATUS_SUCCESS) return false;
    }

    if (!g_lt_state.workspace) {
        cudaMalloc(&g_lt_state.workspace, g_lt_state.workspace_size);
    }

    cublasOperation_t transa = CUBLAS_OP_T;
    cublasOperation_t transb = CUBLAS_OP_N;

    cublasLtMatmulDescCreate(&g_lt_state.op_desc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    cublasLtMatmulDescSetAttribute(g_lt_state.op_desc, CUBLASLT_MATMUL_DESC_TRANSA,
                                   &transa, sizeof(transa));
    cublasLtMatmulDescSetAttribute(g_lt_state.op_desc, CUBLASLT_MATMUL_DESC_TRANSB,
                                   &transb, sizeof(transb));

    cublasLtMatrixLayoutCreate(&g_lt_state.layout_a, CUDA_R_32F, K, N, K);
    cublasLtMatrixLayoutCreate(&g_lt_state.layout_b, CUDA_R_32F, K, M, K);
    cublasLtMatrixLayoutCreate(&g_lt_state.layout_c, CUDA_R_32F, N, M, N);

    cublasLtMatmulPreference_t pref;
    cublasLtMatmulPreferenceCreate(&pref);
    cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                                         &g_lt_state.workspace_size, sizeof(g_lt_state.workspace_size));

    int returned = 0;
    cublasStatus_t stat = cublasLtMatmulAlgoGetHeuristic(
        g_lt_state.handle, g_lt_state.op_desc,
        g_lt_state.layout_a, g_lt_state.layout_b,
        g_lt_state.layout_c, g_lt_state.layout_c,
        pref, 1, &g_lt_state.algo_result, &returned);
    cublasLtMatmulPreferenceDestroy(pref);

    g_lt_state.initialized = (stat == CUBLAS_STATUS_SUCCESS && returned > 0);
    if (g_lt_state.initialized) {
        g_lt_state.cached_M = M;
        g_lt_state.cached_N = N;
        g_lt_state.cached_K = K;
    }
    return g_lt_state.initialized;
}

// ---------------------------------------------------------------------------
// Exported fused entrypoint
// ---------------------------------------------------------------------------

torch::Tensor fused_linear_groupnorm_swish_multiply_swish(
    torch::Tensor x,
    torch::Tensor linear_weight,
    torch::Tensor linear_bias,
    torch::Tensor gn_weight,
    torch::Tensor gn_bias,
    torch::Tensor multiply_weight,
    int64_t num_groups,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat, "x must be float32");

    int M = (int)x.size(0);
    int K = (int)x.size(1);
    int N = (int)linear_weight.size(0);

    auto out = torch::empty({M, N}, x.options());

    bool use_lt = init_cublaslt(M, N, K);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (use_lt) {
        float alpha = 1.0f, beta = 0.0f;
        cublasLtMatmul(
            g_lt_state.handle,
            g_lt_state.op_desc,
            &alpha,
            linear_weight.data_ptr<float>(),
            g_lt_state.layout_a,
            x.data_ptr<float>(),
            g_lt_state.layout_b,
            &beta,
            out.data_ptr<float>(),
            g_lt_state.layout_c,
            out.data_ptr<float>(),
            g_lt_state.layout_c,
            &g_lt_state.algo_result.algo,
            g_lt_state.workspace,
            g_lt_state.workspace_size,
            stream);

        if (linear_bias.defined() && linear_bias.numel() > 0) {
            out = out + linear_bias.unsqueeze(0);
        }
    } else {
        out = at::linear(x, linear_weight, linear_bias);
        if (!out.is_contiguous()) out = out.contiguous();
    }

    int rows     = out.size(0);
    int channels = out.size(1);

    launch_epilogue(
        out.data_ptr<float>(),
        gn_weight.data_ptr<float>(),
        gn_bias.data_ptr<float>(),
        multiply_weight.data_ptr<float>(),
        rows, channels, (int)num_groups, (float)eps);

    return out;
}
